WITH lines AS (SELECT id, customer_id, element FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) t AS element) SELECT s.id, s.customer_id, s.element, CASE WHEN element RLIKE '^(SPRING10|VIP)$' THEN 'PRIORITY' WHEN element RLIKE '^(BUNDLE|WELCOME5)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS element_zone, (SELECT MAX(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS max_subscription_monthly_fee FROM lines s;
